// Simplified sketch (C-like, using JS-style syntax for clarity)
typedef struct { atomic_int credits; int core; waitqueue_t wq; } thread_t;

void on_tick(int core){
  for (each t in core_list[core]){
    int c = atomic_load(&t->credits);
    if (c < MAX) atomic_fetch_add(&t->credits, 1);
  }
  wake_one_from_wq(core);
}

int spend_credit(thread_t* t, int cost){
  int prev = atomic_fetch_sub(&t->credits, cost);
  return prev - cost;
}
